// Offline end-to-end: real mpv plays through the sidecar from a fake SABR pump that serves real
// media (DASH-style VP9/Opus WebM with Cues up front, generated by ffmpeg at test time) with
// network-like latency. Start at 4 s, play, seek to 40 s via mpv's IPC, play on. No YouTube.
// Skipped when ffmpeg or mpv is missing.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync, spawn } from 'node:child_process';
import { mod, fakeYouTube, startApp, get, until, sleep } from './helpers.mjs';
import { mpvIpc } from './mpvipc.mjs';

const FFMPEG = process.env.SOFA_FFMPEG || '/opt/local/bin/ffmpeg';
const MPV = process.env.SOFA_MPV || '/opt/local/bin/mpv';
const have = fs.existsSync(FFMPEG) && fs.existsSync(MPV);
const env = { ...process.env };
delete env.DYLD_INSERT_LIBRARIES;

const { parseIndex } = await mod('lib/mediaindex.mjs');
const { Breaker } = await mod('lib/breaker.mjs');

function gen(dir) {
  const common = ['-hide_banner', '-loglevel', 'error', '-y'];
  const dash = ['-f', 'webm', '-dash', '1', '-cluster_time_limit', '2000', '-cues_to_front', '1', '-reserve_index_space', '8192'];
  // noise keeps the bitrate at 2 Mbit/s: 60 s = 15 MB, far more than socket buffers hold, so mpv
  // really has to seek over HTTP (a tiny file would just be read through)
  let r = spawnSync(FFMPEG, [...common, '-f', 'lavfi', '-i', 'testsrc2=size=426x240:rate=25,noise=alls=30:allf=t', '-t', '60',
    '-c:v', 'libvpx-vp9', '-b:v', '2M', '-minrate', '2M', '-maxrate', '2M', '-g', '50', '-keyint_min', '50', '-deadline', 'realtime', '-cpu-used', '8', '-an', ...dash, path.join(dir, 'v.webm')], { env });
  if (r.status !== 0) throw new Error(`ffmpeg video: ${r.stderr}`);
  r = spawnSync(FFMPEG, [...common, '-f', 'lavfi', '-i', 'sine=f=440:r=48000', '-t', '60', '-c:a', 'libopus', '-b:a', '48k', '-vn', ...dash, path.join(dir, 'a.webm')], { env });
  if (r.status !== 0) throw new Error(`ffmpeg audio: ${r.stderr}`);
}

/** Pump serving real file bytes, segment by segment, with latency like a SABR response. */
function filePumps(files, { firstMs = 400, stepMs = 120 } = {}) {
  const log = { starts: [], live: 0 };
  const media = {};
  for (const [key, file] of Object.entries(files)) {
    const buf = fs.readFileSync(file);
    const ix = parseIndex(buf, file.endsWith('a.webm') ? 'audio/webm' : 'video/webm');
    media[key] = { init: buf.subarray(0, ix[0].off), segs: ix.map((e, i) => ({
      start: e.off, buf: buf.subarray(e.off, ix[i + 1] ? ix[i + 1].off : buf.length), startMs: e.ms,
      durationMs: (ix[i + 1] ? ix[i + 1].ms : 60000) - e.ms })) };
  }
  function start(_info, _f, o) {
    log.starts.push({ video: o.video?.key || null, audio: o.audio.key, startMs: o.startMs });
    log.live++;
    let stop = false; let timer;
    const cur = [o.video ? ['video', media[o.video.key]] : null, ['audio', media[o.audio.key]]].filter(Boolean).map(([kind, m]) => ({
      kind, m, init: false, i: Math.max(0, m.segs.findLastIndex((s) => s.startMs <= o.startMs)) }));
    const end = (how) => { if (!stop) { stop = true; log.live--; clearTimeout(timer); o.onEnd(null, how); } };
    const step = () => {
      if (stop) return;
      let any = false;
      for (const c of cur) {
        if (!c.init) { c.init = true; any = true; o.onSegment(c.kind, { start: 0, buf: Buffer.from(c.m.init), startMs: 0, durationMs: 0, init: true }); }
        else if (c.i < c.m.segs.length) { const s = c.m.segs[c.i++]; any = true; o.onSegment(c.kind, { ...s, buf: Buffer.from(s.buf), init: false }); }
        if (stop) return;
      }
      if (!any) return end('finished');
      timer = setTimeout(step, stepMs);
    };
    timer = setTimeout(step, firstMs);
    return { abort: () => end('aborted') };
  }
  return { start, log, media };
}

test('mpv plays and seeks through the sidecar (real media, fake SABR)', { skip: !have && 'ffmpeg/mpv missing', timeout: 90000 }, async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sofa-yt-mpv-'));
  gen(dir);
  const vsize = fs.statSync(path.join(dir, 'v.webm')).size;
  const asize = fs.statSync(path.join(dir, 'a.webm')).size;
  const vix = parseIndex(fs.readFileSync(path.join(dir, 'v.webm')), 'video/webm');
  const aix = parseIndex(fs.readFileSync(path.join(dir, 'a.webm')), 'audio/webm');
  const info = {
    id: 'testtesttes', title: 'generated', durationMs: 60000, expires: Date.now() / 1000 + 3600, sabrUrl: 'x', ustreamer: 'x',
    clientName: 1, clientVersion: '2', captions: null,
    formats: [
      { itag: 242, mimeType: 'video/webm; codecs="vp9"', bitrate: 2000000, width: 426, height: 240, fps: 25, qualityLabel: '240p', quality: 'small',
        contentLength: String(vsize), approxDurationMs: '60000', initRange: { start: '0', end: '200' }, indexRange: { start: '201', end: String(vix[0].off - 1) }, lastModified: '1' },
      { itag: 251, mimeType: 'audio/webm; codecs="opus"', bitrate: 48000, audioQuality: 'AUDIO_QUALITY_MEDIUM', contentLength: String(asize),
        approxDurationMs: '60000', initRange: { start: '0', end: '200' }, indexRange: { start: '201', end: String(aix[0].off - 1) }, lastModified: '1' },
    ],
  };
  const pumps = filePumps({ 242: path.join(dir, 'v.webm'), 251: path.join(dir, 'a.webm') }, { firstMs: Number(process.env.SOFA_YT_TEST_FIRST_MS || 400) });
  const app = await startApp({ youtube: fakeYouTube({ testtesttes: info }), po: { state: 'ready' }, breaker: new Breaker(null),
    startPump: pumps.start, sessionCfg: { LOW_MS: 4000, HIGH_MS: 8000, GRACE_MS: 1500 } });
  const sock = path.join(dir, 'mpv.sock');
  let mpv; let mlog = '';
  try {
    const o = JSON.parse((await get(`${app.base}/open?v=testtesttes&start=4`)).body);
    assert.equal(o.vitag, 242);
    mpv = spawn(MPV, ['--no-config', '--vo=null', '--ao=null', '--cache=no', '--demuxer-readahead-secs=2', `--input-ipc-server=${sock}`,
      '--start=4', '--msg-level=all=v', o.video, `--audio-file=${o.audio}`], { env, stdio: ['ignore', 'pipe', 'pipe'] });
    mpv.stdout.on('data', (d) => { mlog += d; });
    mpv.stderr.on('data', (d) => { mlog += d; });
    const exited = new Promise((r) => mpv.on('exit', r));
    assert.ok(await until(() => fs.existsSync(sock), 15000), 'mpv IPC socket');
    const ipc = mpvIpc(sock);
    await ipc.ready;
    const pos = async () => (await ipc.get('time-pos')) ?? -1;
    assert.ok(await until(async () => (await pos()) >= 4.5, 20000, 100), 'plays from 4 s');
    assert.ok(await until(async () => (await pos()) >= 7, 20000, 100), 'keeps playing');
    await ipc.cmd('seek', 40, 'absolute');
    assert.ok(await until(async () => { const p = await pos(); return p >= 40.3 && p < 50; }, 20000, 100), 'plays after seeking to 40 s');
    assert.ok(await until(async () => (await pos()) >= 42, 20000, 100), 'keeps playing after the seek');
    assert.ok(pumps.log.starts.some((s) => s.video === '242' && s.startMs >= 38000 && s.startMs <= 40000), `SABR restarted near 40 s: ${JSON.stringify(pumps.log.starts)}`);
    await ipc.cmd('quit');
    ipc.close();
    assert.equal(await Promise.race([exited, sleep(10000).then(() => 'timeout')]), 0);
    mpv = null;
  } catch (e) {
    e.message += `\n--- mpv log (tail) ---\n${mlog.split('\n').filter((l) => /ffmpeg|http|stream|seek|demux|error|Exiting/i.test(l)).slice(-60).join('\n')}`;
    throw e;
  } finally {
    if (mpv && mpv.exitCode === null) mpv.kill('SIGKILL');
    await app.close();
    fs.rmSync(dir, { recursive: true, force: true });
  }
});
